CREATE FUNCTION public.social_target_visible(_post uuid,_reel uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _post IS NOT NULL AND _reel IS NULL THEN EXISTS(SELECT 1 FROM public.posts p WHERE p.id=_post AND public.post_listing_visible(p) AND public.account_allowed(p.user_id)) WHEN _reel IS NOT NULL AND _post IS NULL THEN EXISTS(SELECT 1 FROM public.reels r WHERE r.id=_reel AND r.published AND public.account_allowed(r.user_id)) ELSE false END $$;
REVOKE ALL ON FUNCTION public.social_target_visible(uuid,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.social_target_visible(uuid,uuid) TO anon,authenticated,service_role;
ALTER POLICY comments_read ON public.comments USING(public.social_target_visible(post_id,reel_id));
ALTER POLICY comments_add ON public.comments WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND public.social_target_visible(post_id,reel_id));
CREATE POLICY comments_own_history ON public.comments FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
ALTER POLICY likes_add ON public.likes WITH CHECK(user_id=auth.uid() AND public.account_allowed(auth.uid()) AND public.social_target_visible(post_id,reel_id));
CREATE OR REPLACE FUNCTION public.social_like_count(_post uuid DEFAULT NULL,_reel uuid DEFAULT NULL) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT count(*) FROM public.likes l WHERE public.social_target_visible(_post,_reel) AND ((_post IS NOT NULL AND l.post_id=_post) OR (_reel IS NOT NULL AND l.reel_id=_reel)) $$;